/* ============================================================================
 * Icon library — extracted from the Exploration pt-II Figma (node 943-29146
 * and the shared icon set). Paths are taken verbatim from the Figma SVGs and
 * normalized to `currentColor` so they inherit text color and respond to
 * tokens. Use these everywhere instead of inline one-off SVGs.
 *
 * Add a new icon: paste its Figma path here, set fill/stroke to currentColor,
 * keep the original viewBox, and register it in ICONS for the Storybook gallery.
 * ========================================================================== */

export interface IconProps {
  /** px size (width = height). Default 16. */
  size?: number
  className?: string
  title?: string
}

function svgProps({ size = 16, className, title }: IconProps, viewBox: string) {
  return {
    width: size,
    height: size,
    viewBox,
    fill: 'none' as const,
    xmlns: 'http://www.w3.org/2000/svg',
    className,
    role: title ? ('img' as const) : undefined,
    'aria-hidden': title ? undefined : true,
    'aria-label': title,
  }
}

